// Package ui exposes the generated frontend bundle embedded into the Navi binary.
package ui

import (
	"embed"
	"io/fs"
)

// files includes the frontend distribution generated by `make build-ui`.
//
//go:embed all:dist
var files embed.FS

// Files returns the frontend distribution rooted at dist.
func Files() (fs.FS, error) {
	return fs.Sub(files, "dist")
}
